'use strict';

/**
* Return the index of the last element in a double-precision floating-point strided array equal to a corresponding element in another double-precision floating-point strided array.
*
* @module @stdlib/blas/ext/base/dlast-index-equal
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dlastIndexEqual from '@stdlib/blas/ext/base/dlast-index-equal';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( [ 0.0, 0.0, 3.0, 0.0 ] );
*
* var idx = dlastIndexEqual( x.length, x, 1, y, 1 );
* // returns 2
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import dlastIndexEqual from '@stdlib/blas/ext/base/dlast-index-equal';
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( [ 0.0, 0.0, 3.0, 0.0 ] );
*
* var idx = dlastIndexEqual.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns 2
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var dlastIndexEqual;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlastIndexEqual = main;
} else {
	dlastIndexEqual = tmp;
}


// EXPORTS //

export default dlastIndexEqual;

// exports: { "ndarray": "dlastIndexEqual.ndarray" }
