'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray/base/numel-dimension';
import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import { ndarray as strided } from './../../../../../ext/base/cfill-equal';
import ndarraylike2scalar from '@stdlib/ndarray/base/ndarraylike2scalar';


// MAIN //

/**
* Replaces elements in a one-dimensional single-precision complex floating-point ndarray equal to a provided search element with a specified scalar constant.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the search element.
*     -   a zero-dimensional ndarray containing the scalar constant.
*
* -   When comparing elements, the function checks for equality of real and imaginary components using the strict equality operator `===`. As a consequence, `NaN` components are considered distinct (i.e., as `NaN === NaN` always evaluates to `false`, elements having one or more `NaN` components are never replaced), and `-0` and `+0` are considered the same.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} input ndarray
*
* @example
* import Complex64Vector from '@stdlib/ndarray/vector/complex64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import Complex64 from '@stdlib/complex/float32/ctor';
*
* var x = new Complex64Vector( [ 0.0, 0.0, -2.0, 3.0, 0.0, 0.0, 4.0, -6.0 ] );
*
* var searchElement = scalar2ndarray( new Complex64( 0.0, 0.0 ), {
*     'dtype': 'complex64'
* });
*
* var alpha = scalar2ndarray( new Complex64( 5.0, 5.0 ), {
*     'dtype': 'complex64'
* });
*
* var out = cfillEqual( [ x, searchElement, alpha ] );
* // returns <ndarray>[ <Complex64>[ 5.0, 5.0 ], <Complex64>[ -2.0, 3.0 ], <Complex64>[ 5.0, 5.0 ], <Complex64>[ 4.0, -6.0 ] ]
*/
function cfillEqual( arrays ) {
	var searchElement;
	var alpha;
	var x;

	x = arrays[ 0 ];
	searchElement = ndarraylike2scalar( arrays[ 1 ] );
	alpha = ndarraylike2scalar( arrays[ 2 ] );
	strided( numelDimension( x, 0 ), searchElement, alpha, getData( x ), getStride( x, 0 ), getOffset( x ) ); // eslint-disable-line max-len
	return x;
}


// EXPORTS //

export default cfillEqual;
