'use strict';

/**
* Compute the sum of a one-dimensional single-precision floating-point ndarray, ignoring `NaN` values and using an improved Kahan–Babuška algorithm.
*
* @module @stdlib/blas/ext/base/ndarray/snansumkbn
*
* @example
* import Float32Vector from '@stdlib/ndarray/vector/float32';
* import snansumkbn from '@stdlib/blas/ext/base/ndarray/snansumkbn';
*
* var x = new Float32Vector( [ 1.0, -2.0, NaN, 2.0 ] );
*
* var v = snansumkbn( [ x ] );
* // returns 1.0
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var snansumkbn;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	snansumkbn = main;
} else {
	snansumkbn = tmp;
}


// EXPORTS //

export default snansumkbn;
