'use strict';

/**
* Return the index of the last falsy element in a double-precision complex floating-point strided array.
*
* @module @stdlib/blas/ext/base/zlast-index-of-falsy
*
* @example
* import Complex128Array from '@stdlib/array/complex128';
* import zlastIndexOfFalsy from '@stdlib/blas/ext/base/zlast-index-of-falsy';
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0, 4.0, 5.0 ] );
*
* var idx = zlastIndexOfFalsy( x.length, x, 1 );
* // returns 4
*
* @example
* import Complex128Array from '@stdlib/array/complex128';
* import zlastIndexOfFalsy from '@stdlib/blas/ext/base/zlast-index-of-falsy';
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0, 0.0, 0.0, 2.0, 3.0, 0.0, 0.0, 4.0, 5.0 ] );
*
* var idx = zlastIndexOfFalsy.ndarray( x.length, x, 1, 0 );
* // returns 4
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var zlastIndexOfFalsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zlastIndexOfFalsy = main;
} else {
	zlastIndexOfFalsy = tmp;
}


// EXPORTS //

export default zlastIndexOfFalsy;

// exports: { "ndarray": "zlastIndexOfFalsy.ndarray" }
